import heapq

def match(orders):
    trades = []
    seq_counter = 0

    # order_id -> dict with info: side, price, qty (remaining), seq, active
    book = {}

    # heaps: store (key, seq, order_id)
    buy_heap = []   # max-heap by price -> store -price
    sell_heap = []  # min-heap by price

    def push_buy(order_id):
        o = book[order_id]
        heapq.heappush(buy_heap, (-o['price'], o['seq'], order_id))

    def push_sell(order_id):
        o = book[order_id]
        heapq.heappush(sell_heap, (o['price'], o['seq'], order_id))

    def top_valid_buy():
        while buy_heap:
            negprice, s, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return oid
        return None

    def top_valid_sell():
        while sell_heap:
            price, s, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return oid
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq = seq_counter
        seq_counter += 1

        book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}

        if side == 'buy':
            while remaining > 0:
                sell_oid = top_valid_sell()
                if sell_oid is None:
                    break
                sell_o = book[sell_oid]
                if price is not None and sell_o['price'] > price:
                    break
                trade_qty = min(remaining, sell_o['qty'])
                trades.append([oid, sell_oid, sell_o['price'], trade_qty])
                remaining -= trade_qty
                sell_o['qty'] -= trade_qty
                book[oid]['qty'] = remaining
                if sell_o['qty'] <= 0:
                    sell_o['active'] = False
                    heapq.heappop(sell_heap)
            book[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                push_buy(oid)
            else:
                if remaining == 0:
                    book[oid]['active'] = False
                else:
                    # ioc/market discard remainder
                    book[oid]['active'] = False

        else:  # sell
            while remaining > 0:
                buy_oid = top_valid_buy()
                if buy_oid is None:
                    break
                buy_o = book[buy_oid]
                if price is not None and buy_o['price'] < price:
                    break
                trade_qty = min(remaining, buy_o['qty'])
                trades.append([buy_oid, oid, buy_o['price'], trade_qty])
                remaining -= trade_qty
                buy_o['qty'] -= trade_qty
                book[oid]['qty'] = remaining
                if buy_o['qty'] <= 0:
                    buy_o['active'] = False
                    heapq.heappop(buy_heap)
            book[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                push_sell(oid)
            else:
                if remaining == 0:
                    book[oid]['active'] = False
                else:
                    book[oid]['active'] = False

    return trades

